#!/usr/bin/env node
// Offline check of one operation's input against the API spec, without
// calling anything:
//
//   node validate.mjs path/to/call.json
//   node validate.mjs '{"operation":"listPets","input":{"limit":10}}'
//
// `input` is the request body, or, for an operation without one, an object of
// its parameters by name. Other keys of the call are ignored.
//
// Prints OK, or one line per problem with a suggestion, and exits non-zero.
// It knows operation names, input keys, value types and enum values, not
// whether the data exists. Generated by openapi-to-skills.
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

function distance(a, b) {
	const row = Array.from({ length: b.length + 1 }, (_, i) => i);
	for (let i = 1; i <= a.length; i++) {
		let prev = row[0];
		row[0] = i;
		for (let j = 1; j <= b.length; j++) {
			const cur = row[j];
			row[j] = Math.min(
				row[j] + 1,
				row[j - 1] + 1,
				prev + (a[i - 1] === b[j - 1] ? 0 : 1),
			);
			prev = cur;
		}
	}
	return row[b.length];
}

// Closest known names: substring matches first, then small edit distance.
function near(key, known) {
	const k = String(key).toLowerCase();
	return known
		.map((c) => {
			const l = String(c).toLowerCase();
			return { c, d: l.includes(k) || k.includes(l) ? 0 : distance(k, l) };
		})
		.filter((x) => x.d <= Math.max(2, Math.floor(k.length / 3)))
		.sort((a, b) => a.d - b.d || String(a.c).length - String(b.c).length)
		.slice(0, 5)
		.map((x) => x.c);
}

// The suffixes a filter schema uses: what follows a known key in another
// known key ("_in" when both "name" and "name_in" exist).
function filterSuffixes(known) {
	const suffixes = new Set();
	const keys = new Set(known);
	for (const key of known) {
		for (let i = key.indexOf("_"); i > 0; i = key.indexOf("_", i + 1))
			if (keys.has(key.slice(0, i))) suffixes.add(key.slice(i));
	}
	return suffixes;
}

const didYouMean = (hint) =>
	hint.length ? `; did you mean ${hint.join(", ")}?` : "";

/**
 * Check a call ({operation, input}) against the generated data. Returns the
 * problems found, each a line of text; none means the call is well formed.
 */
export function validate(data, call) {
	const issues = [];
	const warnings = [];

	const resolve = (type) => {
		const seen = new Set();
		while (type?.ref) {
			if (seen.has(type.ref)) return undefined;
			seen.add(type.ref);
			type = data.schemas[type.ref];
		}
		return type;
	};

	const describe = (type) => {
		const t = resolve(type);
		if (!t) return "a value";
		if (t.enum)
			return t.enum.length <= 12
				? `one of ${t.enum.map((v) => JSON.stringify(v)).join(", ")}`
				: "an enum value";
		if (t.oneOf) return t.oneOf.map(describe).join(" or ");
		return (
			{
				string: "a string",
				number: "a number",
				integer: "an integer",
				boolean: "a boolean",
				array: "an array",
				object: "an object",
			}[t.type] ?? "a value"
		);
	};

	const allowedValues = (values, value) => {
		if (values.length <= 12)
			return values.map((v) => JSON.stringify(v)).join(", ");
		const close = near(value, values.map(String));
		return `${values.length} values${close.length ? `, closest: ${close.join(", ")}` : ""}`;
	};

	function check(value, type, path, filter) {
		if (value === undefined) return;
		const ref = type?.ref;
		const t = resolve(type);
		if (!t) return;
		if (value === null) {
			if (!t.nullable && !type.nullable)
				issues.push(`${path}: must not be null`);
			return;
		}
		if (t.oneOf) {
			// Accepted when any variant accepts it.
			const before = issues.length;
			for (const variant of t.oneOf) {
				const mark = issues.length;
				check(value, variant, path, filter);
				if (issues.length === mark) {
					issues.length = before;
					return;
				}
			}
			issues.length = before;
			issues.push(`${path}: expected ${describe(t)}`);
			return;
		}
		// A scalar (an enum value too) given as an object or a list: say so,
		// and in a filter, how operators are written instead.
		const scalar =
			t.enum || ["string", "number", "integer", "boolean"].includes(t.type);
		if (scalar && typeof value === "object") {
			const key = path.split(".").pop();
			const operators = filter
				? `; filter operators are key suffixes like ${key}_in, not nested objects: write {"${key}_in": [...]}`
				: "";
			return issues.push(
				`${path}: expected ${t.enum && t.enum.length > 12 ? "one value" : describe(t)}, not ${Array.isArray(value) ? "an array" : "an object"}${operators}`,
			);
		}
		if (t.enum) {
			if (!t.enum.includes(value))
				issues.push(
					`${path}: ${JSON.stringify(value)} is not valid; allowed: ${allowedValues(t.enum, value)}`,
				);
			return;
		}
		switch (t.type) {
			case "array":
				if (!Array.isArray(value))
					return issues.push(
						`${path}: expected an array of ${describe(t.items)}`,
					);
				value.forEach((item, i) => {
					check(item, t.items, `${path}[${i}]`);
				});
				return;
			case "object": {
				if (typeof value !== "object" || Array.isArray(value))
					return issues.push(`${path}: expected an object`);
				const isFilter = ref !== undefined && data.filters?.includes(ref);
				checkObject(value, t, path, isFilter);
				return;
			}
			case "string":
			case "number":
			case "integer":
			case "boolean": {
				const ok =
					t.type === "string"
						? typeof value === "string"
						: t.type === "boolean"
							? typeof value === "boolean"
							: typeof value === "number" &&
								(t.type === "number" || Number.isInteger(value));
				if (!ok)
					issues.push(
						`${path}: expected ${describe(t)}, got ${JSON.stringify(value)}`,
					);
				return;
			}
			default:
				return;
		}
	}

	function checkObject(value, t, path, isFilter) {
		const props = t.props ?? {};
		const known = Object.keys(props);
		for (const [key, v] of Object.entries(value)) {
			if (key in props) {
				check(v, props[key], `${path}.${key}`, isFilter);
				continue;
			}
			if (t.values) {
				check(v, t.values, `${path}.${key}`);
				continue;
			}
			// In a filter, a wrong operator on a right field lists the keys
			// that field does have: the longest known key the key starts with.
			// A field may have no key of its own (only suffixed ones), so a
			// prefix counts as a field when every key under it is the prefix
			// plus a suffix some other field also uses.
			let candidates = [];
			if (isFilter) {
				const suffixes = filterSuffixes(known);
				const parts = key.split("_");
				for (let n = parts.length - 1; n > 0 && !candidates.length; n--) {
					const field = parts.slice(0, n).join("_");
					const under = known.filter(
						(k) => k === field || k.startsWith(`${field}_`),
					);
					if (
						under.length &&
						under.every(
							(k) => k === field || suffixes.has(k.slice(field.length)),
						)
					)
						candidates = under;
				}
			}
			const hint = near(key, known);
			const extra =
				isFilter && candidates.length && candidates.length <= 16
					? `; keys for this field: ${candidates.join(", ")}`
					: didYouMean(hint);
			const line = `${path}.${key}: unknown key${extra}`;
			// A filter's keys are all its keys: anything else is a mistake.
			if (t.closed || isFilter) issues.push(line);
			else warnings.push(`${line} (not in the spec; it may be ignored)`);
		}
		for (const key of t.required ?? [])
			if (value[key] === undefined)
				issues.push(`${path}.${key}: required, missing`);
	}

	if (!call || typeof call !== "object") {
		return {
			issues: ["expected a JSON object with operation and input"],
			warnings,
		};
	}
	if (call.input === undefined && call.body !== undefined)
		issues.push('body: the operation\'s input goes under "input", not "body"');

	const operation = data.operations[call.operation];
	if (!operation) {
		const hint = call.operation
			? near(call.operation, Object.keys(data.operations))
			: [];
		issues.push(
			`operation: ${call.operation ? `"${call.operation}" is not an operation in this skill` : "missing"}${didYouMean(hint)}`,
		);
		return { issues, warnings };
	}

	const input = call.input;
	if (operation.body) {
		if (input === undefined) {
			if (operation.bodyRequired) issues.push("input: required, missing");
		} else check(input, operation.body, "input");
	} else if (operation.params) {
		check(
			input ?? {},
			{ type: "object", closed: true, ...operation.params },
			"input",
		);
	} else if (input !== undefined && Object.keys(input ?? {}).length) {
		issues.push("input: this operation takes no input");
	}
	return { issues, warnings };
}

function main(arg) {
	if (!arg) {
		console.error("usage: node validate.mjs <call.json | inline JSON>");
		process.exit(2);
	}
	let call;
	try {
		call = JSON.parse(existsSync(arg) ? readFileSync(arg, "utf8") : arg);
	} catch (e) {
		console.error(`not JSON: ${e.message}`);
		process.exit(2);
	}
	const here = dirname(fileURLToPath(import.meta.url));
	const data = JSON.parse(
		readFileSync(join(here, "validate-data.json"), "utf8"),
	);
	const { issues, warnings } = validate(data, call);
	for (const line of warnings) console.log(`warning: ${line}`);
	if (issues.length) {
		console.log(issues.join("\n"));
		process.exit(1);
	}
	console.log("OK");
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href)
	main(process.argv[2]);
